    uploadScans: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "device_id": "gate-phone-07",
                 *       "scans": [
                 *         {
                 *           "client_scan_id": "6f1c2d3e-4a5b-4c6d-8e7f-809a1b2c3d4e",
                 *           "ticket_id": "0b0f3a52-7c1e-4d7e-9a57-0c1b4d5e6f70",
                 *           "event_id": 1,
                 *           "gate_group": "N-LOWER",
                 *           "scanned_at": "2026-11-14T11:02:17Z",
                 *           "result": "ADMITTED",
                 *           "token": "TLT1.AQABCw86UnweTX6aVwwbTV5vcAAAAAAAAAABTi1MT1dFUgAAAAAAAAAAAKGyw9Tl9gcY.O5024bVFl6fq-rPKjqJ15KNls5q3woLuzPEG33mc1oS0w-FSiCHxQXjhzotnEv0Wpfr78tSzzMR8KmOHMyk4Dg"
                 *         },
                 *         {
                 *           "client_scan_id": "7a2d3e4f-5b6c-4d7e-9f80-91ab2c3d4e5f",
                 *           "ticket_id": "5e2d9c1a-3b4f-4a6d-8e7f-1a2b3c4d5e6f",
                 *           "event_id": 1,
                 *           "gate_group": "N-LOWER",
                 *           "scanned_at": "2026-11-14T11:02:41Z",
                 *           "result": "ADMITTED"
                 *         }
                 *       ]
                 *     }
                 */
                "application/json": components["schemas"]["ScanBatch"];
            };
        };
        responses: {
            /** @description One result per uploaded scan, in the same order. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "results": [
                     *         {
                     *           "client_scan_id": "6f1c2d3e-4a5b-4c6d-8e7f-809a1b2c3d4e",
                     *           "ticket_id": "0b0f3a52-7c1e-4d7e-9a57-0c1b4d5e6f70",
                     *           "result": "ADMITTED",
                     *           "overridden": false,
                     *           "ticket_status": "USED",
                     *           "first_admitted_at": "2026-11-14T11:02:17Z"
                     *         },
                     *         {
                     *           "client_scan_id": "7a2d3e4f-5b6c-4d7e-9f80-91ab2c3d4e5f",
                     *           "ticket_id": "5e2d9c1a-3b4f-4a6d-8e7f-1a2b3c4d5e6f",
                     *           "result": "DUPLICATE",
                     *           "overridden": true,
                     *           "ticket_status": "USED",
                     *           "first_admitted_at": "2026-11-14T10:58:03Z"
                     *         }
                     *       ]
                     *     }
                     */
                    "application/json": components["schemas"]["ScanBatchResult"];
                };
            };
            400: components["responses"]["ValidationFailed"];
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["Forbidden"];
            /** @description `EVENT_BUSY` - an event of the batch is being cancelled or edited. Nothing was stored; send the batch again. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description `PAYLOAD_TOO_LARGE` - more than 500 scans, or a body over 1 MiB. Split the batch. */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            429: components["responses"]["TooManyRequests"];
            500: components["responses"]["Internal"];
        };
    };
